import{_ as d,o as a,c as e,aj as r}from"./framework.js";const p=JSON.parse('{"title":"添加内容 | Quick Start | Documentation","description":"添加内容 in Kooboo: 数据类型决定内容字段。第一次建议从简单模型开始：","frontmatter":{"title":"添加内容 | Quick Start | Documentation","description":"添加内容 in Kooboo: 数据类型决定内容字段。第一次建议从简单模型开始：","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/quick-start/add-content.html"}]]},"headers":[],"relativePath":"zh/quick-start/add-content.md","filePath":"quick-start/add-content.md","lastUpdated":1780991406000}'),o={name:"zh/quick-start/add-content.md"};function h(n,t,i,c,l,s){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="添加内容" tabindex="-1">添加内容 <a class="header-anchor" href="#添加内容" aria-label="Permalink to &quot;添加内容&quot;">​</a></h1><blockquote><p>建立内容模型与内容条目，让页面从后台读取数据。</p></blockquote><h2 id="先建数据类型" tabindex="-1">先建数据类型 <a class="header-anchor" href="#先建数据类型" aria-label="Permalink to &quot;先建数据类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>菜单路径</td><td>站点后台 -&gt; 内容 -&gt; 数据类型</td></tr><tr><td>深链</td><td><code>/_Admin/contents/types?SiteId={站点GUID}</code></td></tr><tr><td>详细文档</td><td><a href="/kb-docs/zh/cms/content/content-types.html">CMS：数据类型</a></td></tr></tbody></table><p>数据类型决定内容字段。第一次建议从简单模型开始：</p><table tabindex="0"><thead><tr><th>场景</th><th>字段建议</th></tr></thead><tbody><tr><td>新闻</td><td>标题、摘要、封面、正文、发布日期</td></tr><tr><td>产品展示</td><td>名称、图片、简介、价格、排序</td></tr><tr><td>FAQ</td><td>问题、答案、分类、是否置顶</td></tr></tbody></table><h2 id="再建内容文件夹" tabindex="-1">再建内容文件夹 <a class="header-anchor" href="#再建内容文件夹" aria-label="Permalink to &quot;再建内容文件夹&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>菜单路径</td><td>站点后台 -&gt; 内容 -&gt; 内容</td></tr><tr><td>深链</td><td><code>/_Admin/contents?SiteId={站点GUID}</code></td></tr><tr><td>详细文档</td><td><a href="/kb-docs/zh/cms/content/contents-folders-list.html">CMS：内容列表</a></td></tr></tbody></table><p>内容文件夹把一个数据类型变成可维护的数据集合。创建后进入文件夹，添加几条内容作为页面测试数据。</p><h2 id="在页面中使用内容" tabindex="-1">在页面中使用内容 <a class="header-anchor" href="#在页面中使用内容" aria-label="Permalink to &quot;在页面中使用内容&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>适合场景</th><th>文档</th></tr></thead><tbody><tr><td>模板绑定</td><td>页面直接渲染列表、详情、字段</td><td><a href="/kb-docs/zh/templateEngine/binding/">模板绑定语法</a></td></tr><tr><td><code>k-data</code></td><td>在模板中声明查询、映射与导出</td><td><a href="/kb-docs/zh/templateEngine/k-data/">k-data</a></td></tr><tr><td>KScript API</td><td>前端通过 JSON 接口读取内容</td><td><a href="/kb-docs/zh/api/content/">k.content</a></td></tr></tbody></table><p>如果你还不准备写脚本，优先用模板绑定或 <code>k-data</code>；需要筛选、分页、权限或跨端数据时，再写 API。</p><h2 id="常见检查" tabindex="-1">常见检查 <a class="header-anchor" href="#常见检查" aria-label="Permalink to &quot;常见检查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>检查位置</th></tr></thead><tbody><tr><td>页面没有数据</td><td>内容文件夹是否已有内容，字段名是否与模板一致</td></tr><tr><td>字段显示不对</td><td>数据类型字段类型、必填、默认值</td></tr><tr><td>列表顺序不对</td><td>内容条目的排序、发布时间或查询条件</td></tr><tr><td>多语言内容缺失</td><td>内容语言与站点语言设置</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>继续 <a href="./publish-domain.html">发布与域名</a>，或跳到 <a href="./add-script-api.html">写第一个 KScript API</a>。</p>',16)])])}const m=d(o,[["render",h]]);export{p as __pageData,m as default};
